parameters.functionCode:
// Lead Scoring Algorithm
const lead = items[0].json;

let score = 0;
let priority = 'Low';
let tags = [];

// Budget scoring
if (lead.budget === '$4,000–$10,000+') {
  score += 40;
  tags.push('High Budget');
} else if (lead.budget === '$1,500–$4,000') {
  score += 25;
  tags.push('Medium Budget');
} else if (lead.budget === '$500–$1,200') {
  score += 10;
  tags.push('Starter Budget');
}

// Timeline urgency
if (lead.timeline === 'ASAP') {
  score += 30;
  tags.push('Urgent');
} else if (lead.timeline === '1–2 weeks') {
  score += 20;
  tags.push('Near-term');
} else if (lead.timeline === '2–4 weeks') {
  score += 10;
}

// Goal/Service type scoring
if (lead.goal === 'Internal ops automation') {
  score += 20;
  tags.push('High-Value Service');
} else if (lead.goal === 'Lead capture & follow-up') {
  score += 20;
  tags.push('Marketing Automation');
} else if (lead.goal === 'Customer support automation') {
  score += 15;
  tags.push('Support Automation');
}

// Company presence indicates seriousness
if (lead.company && lead.company.length > 0) {
  score += 10;
  tags.push('Has Company');
}

// Determine priority
if (score >= 70) {
  priority = 'Hot';
  tags.push('🔥 HOT LEAD');
} else if (score >= 40) {
  priority = 'Warm';
  tags.push('⚡ Warm Lead');
} else {
  priority = 'Cold';
  tags.push('❄️ Cold Lead');
}

return [{
  json: {
    ...lead,
    score: score,
    priority: priority,
    tags: tags,
    capturedAt: new Date().toISOString(),
    status: 'New',
    followUpDate: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString() // Tomorrow
  }
}];

